record.field:
moved, skipped = 0, 0
for po in records:
    if po.x_approval_state == 'draft':
        po.action_submit()
        moved += 1
    else:
        skipped += 1
action = {
    'type': 'ir.actions.client', 'tag': 'display_notification',
    'params': {
        'title': 'Submit to Board — complete',
        'message': f'{moved} requisition(s) submitted to Board queue. {skipped} skipped (not in Draft state).',
        'type': 'success' if moved else 'warning',
        'sticky': False,
    },
}

moved, skipped = 0, 0
for po in records:
    if po.x_approval_state == 'board':
        po.action_board_approve()
        moved += 1
    else:
        skipped += 1
action = {
    'type': 'ir.actions.client', 'tag': 'display_notification',
    'params': {
        'title': 'Board Approve — complete',
        'message': f'{moved} requisition(s) advanced to Floor queue. {skipped} skipped (not in Board state).',
        'type': 'success' if moved else 'warning',
        'sticky': False,
    },
}

moved, skipped = 0, 0
for po in records:
    if po.x_approval_state == 'floor':
        po.action_floor_approve()
        moved += 1
    else:
        skipped += 1
action = {
    'type': 'ir.actions.client', 'tag': 'display_notification',
    'params': {
        'title': 'Floor Approve — complete',
        'message': f'{moved} requisition(s) approved. {skipped} skipped (not in Floor state).',
        'type': 'success' if moved else 'warning',
        'sticky': False,
    },
}
